mask2={ (1,c) for c in range(3,10)} | {(2,3),(2,9)} | {(3,3),(3,5),(3,6),(3,7),(3,9)} | {(4,1),(4,3),(4,5),(4,7),(4,9)} | {(5,1),(5,3),(5,5),(5,7),(5,9)} | {(6,1),(6,3),(6,7),(6,9)} | {(7,1),(7,3),(7,4),(7,5),(7,6),(7,7),(7,9)} | {(8,1),(8,9)} | {(9,c) for c in range(1,10)}
# translate +1 col, clipping outside board
mask={(r,c+1) for r,c in mask2 if c+1<11}
obs={(0,10),(1,1),(1,6),(3,1),(5,3),(5,8),(8,0),(9,1),(9,10),(10,6)}
# flood over mask from center, only 4-connectivity; initial seed included?
start=(5,6)
seen={start} if start in mask else set(); stack=list(seen)
while stack:
 r,c=stack.pop()
 for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
  if q in mask and q not in obs and q not in seen:
   seen.add(q);stack.append(q)
print(len(mask),len(seen), sorted(seen))
out=[[0]*11 for _ in range(11)]
for r,c in seen: out[r][c]=3
for r,c in obs: out[r][c]=2
for row in out: print(row)

